binaryInsertion(A,n):
    for i=1..n-1:
        x=A[i]；low=0；high=i-1
        while low<=high:
            mid=low+(high-low)//2
            若A[mid]<=x: low=mid+1
            否则high=mid-1
        将A[low..i-1]向右移动1位
        A[low]=x
\end{codeblock}

