void bubbleSort(int A[], int n) {
    for (int end=n-1; end>0; --end) {
        bool changed=false;
        for (int j=0; j<end; ++j)
            if (A[j]>A[j+1]) {
                int x=A[j]; A[j]=A[j+1]; A[j+1]=x;
                changed=true;
            }
        if (!changed) break;
    }
}
\end{codeblock}

