siftDown(A,r,end):
    x=A[r]
    while 2*r<=end:
        c=2*r；若c<end且A[c]<A[c+1]: c++
        若x>=A[c]: break
        A[r]=A[c]；r=c
    A[r]=x
\end{codeblock}

